struct WebPData {
  const uint8_t* bytes;
  size_t size;
};

typedef enum WebPFeatureFlags {
  ANIMATION_FLAG = 0x00000002,
  XMP_FLAG = 0x00000004,
  EXIF_FLAG = 0x00000008,
  ALPHA_FLAG = 0x00000010,
  ICCP_FLAG = 0x00000020,

  ALL_VALID_FLAGS = 0x0000003e
} WebPFeatureFlags;

typedef enum WebPMuxAnimDispose {
  WEBP_MUX_DISPOSE_NONE,       // Do not dispose.
  WEBP_MUX_DISPOSE_BACKGROUND  // Dispose to background color.
} WebPMuxAnimDispose;

typedef enum WebPMuxAnimBlend {
  WEBP_MUX_BLEND,    // Blend.
  WEBP_MUX_NO_BLEND  // Do not blend.
} WebPMuxAnimBlend;

struct WebPRGBABuffer {  // view as RGBA
  uint8_t* rgba;         // pointer to RGBA samples
  int stride;            // stride in bytes from one scanline to the next.
  size_t size;           // total size of the *rgba buffer.
};

struct WebPDecBuffer {
  WEBP_CSP_MODE colorspace;  // Colorspace.
  int width, height;         // Dimensions.
  int is_external_memory;    // If non-zero, 'internal_memory' pointer is not
                             // used. If value is '2' or more, the external
                             // memory is considered 'slow' and multiple
                             // read/write will be avoided.
  union {
    WebPRGBABuffer RGBA;
    WebPYUVABuffer YUVA;
  } u;              // Nameless union of buffer parameters.
  uint32_t pad[4];  // padding for later use

  uint8_t* private_memory;  // Internally allocated memory (only when
                            // is_external_memory is 0). Should not be used
                            // externally, but accessed via the buffer union.
};

typedef enum WEBP_NODISCARD VP8StatusCode {
  VP8_STATUS_OK = 0,
  VP8_STATUS_OUT_OF_MEMORY,
  VP8_STATUS_INVALID_PARAM,
  VP8_STATUS_BITSTREAM_ERROR,
  VP8_STATUS_UNSUPPORTED_FEATURE,
  VP8_STATUS_SUSPENDED,
  VP8_STATUS_USER_ABORT,
  VP8_STATUS_NOT_ENOUGH_DATA
} VP8StatusCode;

struct WebPBitstreamFeatures {
  int width;          // Width in pixels, as read from the bitstream.
  int height;         // Height in pixels, as read from the bitstream.
  int has_alpha;      // True if the bitstream contains an alpha channel.
  int has_animation;  // True if the bitstream is an animation.
  int format;         // 0 = undefined (/mixed), 1 = lossy, 2 = lossless

  uint32_t pad[5];  // padding for later use
};

struct WebPDecoderOptions {
  int bypass_filtering;             // if true, skip the in-loop filtering
  int no_fancy_upsampling;          // if true, use faster pointwise upsampler
  int use_cropping;                 // if true, cropping is applied _first_
  int crop_left, crop_top;          // top-left position for cropping.
                                    // Will be snapped to even values.
  int crop_width, crop_height;      // dimension of the cropping area
  int use_scaling;                  // if true, scaling is applied _afterward_
  int scaled_width, scaled_height;  // final resolution. if one is 0, it is
                                    // guessed from the other one to keep the
                                    // original ratio.
  int use_threads;                  // if true, use multi-threaded decoding
  int dithering_strength;           // dithering strength (0=Off, 100=full)
  int flip;                         // if true, flip output vertically
  int alpha_dithering_strength;     // alpha dithering strength in [0..100]

  uint32_t pad[5];  // padding for later use
};

struct WebPDecoderConfig {
  WebPBitstreamFeatures input;  // Immutable bitstream features (optional)
  WebPDecBuffer output;         // Output buffer (can point to external mem)
  WebPDecoderOptions options;   // Decoding options
};

struct WebPConfig {
  int lossless;
  float quality;
  int method;

  WebPImageHint image_hint;

  int target_size;
  float target_PSNR;
  int segments;
  int sns_strength;
  int filter_strength;
  int filter_sharpness;
  int filter_type;
  int autofilter;
  int alpha_compression;
  int alpha_filtering;
  int alpha_quality;
  int pass;

  int show_compressed;
  int preprocessing;
  int partitions;
  int partition_limit;
  int emulate_jpeg_size;
  int thread_level;
  int low_memory;

  int near_lossless;
  int exact;

  int use_delta_palette;
  int use_sharp_yuv;

  int qmin;
  int qmax;
};

struct WebPPicture {
  int use_argb;

  WebPEncCSP colorspace;
  int width, height;
  uint8_t *y, *u, *v;
  int y_stride, uv_stride;
  uint8_t* a;
  int a_stride;
  uint32_t pad1[2];

  uint32_t* argb;
  int argb_stride;
  uint32_t pad2[3];

  WebPWriterFunction writer;
  void* custom_ptr;

  int extra_info_type;
  uint8_t* extra_info;

  WebPAuxStats* stats;

  WebPEncodingError error_code;

  WebPProgressHook progress_hook;

  void* user_data;

  uint32_t pad3[3];

  uint8_t *pad4, *pad5;
  uint32_t pad6[8];

  void* memory_;
  void* memory_argb_;
  void* pad7[2];
};

struct WebPAuxStats {
  int coded_size;

  float PSNR[5];
  int block_count[3];
  int header_bytes[2];
  int residual_bytes[3][4];
  int segment_size[4];
  int segment_quant[4];
  int segment_level[4];

  int alpha_data_size;
  int layer_data_size;

  uint32_t lossless_features;
  int histogram_bits;
  int transform_bits;
  int cache_bits;
  int palette_size;
  int lossless_size;
  int lossless_hdr_size;
  int lossless_data_size;
  int cross_color_transform_bits;

  uint32_t pad[1];
};

struct WebPMemoryWriter {
  uint8_t* mem;
  size_t size;
  size_t max_size;
  uint32_t pad[1];
};

typedef enum WebPImageHint {
  WEBP_HINT_DEFAULT = 0,
  WEBP_HINT_PICTURE,
  WEBP_HINT_PHOTO,
  WEBP_HINT_GRAPH,
  WEBP_HINT_LAST
} WebPImageHint;

typedef enum WebPPreset {
  WEBP_PRESET_DEFAULT = 0,
  WEBP_PRESET_PICTURE,
  WEBP_PRESET_PHOTO,
  WEBP_PRESET_DRAWING,
  WEBP_PRESET_ICON,
  WEBP_PRESET_TEXT
} WebPPreset;

typedef enum WebPEncCSP {
  WEBP_YUV420 = 0,
  WEBP_YUV420A = 4,
  WEBP_CSP_UV_MASK = 3,
  WEBP_CSP_ALPHA_BIT = 4
} WebPEncCSP;

struct WebPMuxFrameInfo {
  WebPData bitstream;  // image data: can be a raw VP8/VP8L bitstream
                       // or a single-image WebP file.
  int x_offset;        // x-offset of the frame.
  int y_offset;        // y-offset of the frame.
  int duration;        // duration of the frame (in milliseconds).

  WebPChunkId id;  // frame type: should be one of WEBP_CHUNK_ANMF
                   // or WEBP_CHUNK_IMAGE
  WebPMuxAnimDispose dispose_method;  // Disposal method for the frame.
  WebPMuxAnimBlend blend_method;      // Blend operation for the frame.
  uint32_t pad[1];                    // padding for later use
};

struct WebPMuxAnimParams {
  uint32_t bgcolor;  // Background color of the canvas stored (in MSB order) as:
                     // Bits 00 to 07: Alpha.
                     // Bits 08 to 15: Red.
                     // Bits 16 to 23: Green.
                     // Bits 24 to 31: Blue.
  int loop_count;    // Number of times to repeat the animation [0 = infinite].
};

struct WebPAnimEncoderOptions {
  WebPMuxAnimParams anim_params;  // Animation parameters.
  int minimize_size;  // If true, minimize the output size (slow). Implicitly
                      // disables key-frame insertion.
  int kmin;
  int kmax;         // Minimum and maximum distance between consecutive key
                    // frames in the output. The library may insert some key
                    // frames as needed to satisfy this criteria.
                    // Note that these conditions should hold: kmax > kmin
                    // and kmin >= kmax / 2 + 1. Also, if kmax <= 0, then
                    // key-frame insertion is disabled; and if kmax == 1,
                    // then all frames will be key-frames (kmin value does
                    // not matter for these special cases).
  int allow_mixed;  // If true, use mixed compression mode; may choose
                    // either lossy and lossless for each frame.
  int verbose;      // If true, print info and warning messages to stderr.

  uint32_t padding[4];  // Padding for later use.
};

typedef enum WEBP_NODISCARD WebPMuxError {
  WEBP_MUX_OK = 1,
  WEBP_MUX_NOT_FOUND = 0,
  WEBP_MUX_INVALID_ARGUMENT = -1,
  WEBP_MUX_BAD_DATA = -2,
  WEBP_MUX_MEMORY_ERROR = -3,
  WEBP_MUX_NOT_ENOUGH_DATA = -4
} WebPMuxError;

struct WebPIterator {
  int frame_num;
  int num_frames;                     // equivalent to WEBP_FF_FRAME_COUNT.
  int x_offset, y_offset;             // offset relative to the canvas.
  int width, height;                  // dimensions of this frame.
  int duration;                       // display duration in milliseconds.
  WebPMuxAnimDispose dispose_method;  // dispose method for the frame.
  int complete;  // true if 'fragment' contains a full frame. partial images
                 // may still be decoded with the WebP incremental decoder.
  WebPData fragment;  // The frame given by 'frame_num'. Note for historical
                      // reasons this is called a fragment.
  int has_alpha;      // True if the frame contains transparency.
  WebPMuxAnimBlend blend_method;  // Blend operation for the frame.

  uint32_t pad[2];  // padding for later use.
  void* private_;   // for internal use only.
};

struct WebPChunkIterator {
  // The current and total number of chunks with the fourcc given to
  // WebPDemuxGetChunk().
  int chunk_num;
  int num_chunks;
  WebPData chunk;  // The payload of the chunk.

  uint32_t pad[6];  // padding for later use
  void* private_;
};

struct WebPAnimInfo {
  uint32_t canvas_width;
  uint32_t canvas_height;
  uint32_t loop_count;
  uint32_t bgcolor;
  uint32_t frame_count;
  uint32_t pad[4];  // padding for later use
};

struct WebPAnimDecoderOptions {
  // Output colorspace. Only the following modes are supported:
  // MODE_RGBA, MODE_BGRA, MODE_rgbA and MODE_bgrA.
  WEBP_CSP_MODE color_mode;
  int use_threads;      // If true, use multi-threaded decoding.
  uint32_t padding[7];  // Padding for later use.
};

typedef enum WebPDemuxState {
  WEBP_DEMUX_PARSE_ERROR = -1,    // An error occurred while parsing.
  WEBP_DEMUX_PARSING_HEADER = 0,  // Not enough data to parse full header.
  WEBP_DEMUX_PARSED_HEADER = 1,   // Header parsing complete,
                                  // data may be available.
  WEBP_DEMUX_DONE = 2             // Entire file has been parsed.
} WebPDemuxState;

typedef enum WebPFormatFeature {
  WEBP_FF_FORMAT_FLAGS,  // bit-wise combination of WebPFeatureFlags
                         // corresponding to the 'VP8X' chunk (if present).
  WEBP_FF_CANVAS_WIDTH,
  WEBP_FF_CANVAS_HEIGHT,
  WEBP_FF_LOOP_COUNT,        // only relevant for animated file
  WEBP_FF_BACKGROUND_COLOR,  // idem.
  WEBP_FF_FRAME_COUNT        // Number of frames present in the demux object.
                             // In case of a partial demux, this is the number
                             // of frames seen so far, with the last frame
                             // possibly being partial.
} WebPFormatFeature;

