FUZZ_SET_ATTR_INT(mem, "freed", 0);          // not yet freed
FUZZ_SET_ATTR_INT(mem, "size", (int)req_size);  // record requested size for potential checks

// Provide the allocated pointer as an output so the runtime can manage its lifetime.

// Validate that the pointer was allocated by WebPMalloc (or compatible WebP API) and not yet freed.
int is_webp = FUZZ_GET_ATTR_INT(mem, "is_webp_alloc");
if (!is_webp) { FUZZ_BAIL(); }
int was_freed = FUZZ_GET_ATTR_INT(mem, "freed");
if (was_freed) { FUZZ_BAIL(); }

// Free using the matching WebP deallocator and mark as freed to prevent double-free.
WebPFree(mem);
FUZZ_SET_ATTR_INT(mem, "freed", 1);

