WebPDataInit(webp_data);
// Property: After init, bytes must be NULL and size must be 0.
FUZZ_ASSERT(webp_data->bytes == NULL && webp_data->size == 0, "WebPDataInit must zero-initialize bytes/size");
// Validation: Stub enforces writability by using the provided object and asserts post-conditions.

// Prepare webp_data with a buffer allocated via WebPMalloc so WebPDataClear will legitimately free it.
std::string payload = FUZZ_PARAM_STR();
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024u) + 1u;  // keep small for fuzzer perf
if (cap > payload.size()) cap = payload.size();
uint8_t* mem = (uint8_t*)WebPMalloc(cap);
if (mem != NULL) {
  if (cap > 0) memcpy(mem, payload.data(), cap);
  webp_data->bytes = (const uint8_t*)mem;  // WebPData expects const uint8_t*
  webp_data->size = cap;
} else {
  // Allocation failed: leave as empty to respect requirement that freeing NULL is valid.
  webp_data->bytes = NULL;
  webp_data->size = 0;
}
// Call target: must free bytes with WebPFree() and reset fields.
WebPDataClear(webp_data);
// Post-condition: structure must be reset to empty.
FUZZ_ASSERT(webp_data->bytes == NULL && webp_data->size == 0, "WebPDataClear must reset to empty");
// Validation: The stub ensures memory, when present, came from WebPMalloc and asserts idempotent reset semantics.

// Enforce non-aliasing: src and dst must not be the same object.
