// Initialize src with either empty or allocated data (allocated via WebPMalloc per requirements).
bool make_empty = ((*FUZZ_PARAM(unsigned int) % 3u) == 0u);
if (make_empty) {
  src->bytes = NULL;
  src->size = 0;
} else {
  std::string s = FUZZ_PARAM_STR();
